import React from 'react';
import Slider from "react-slick"; // Make sure to install react-slick and slick-carousel

// Import slick-carousel styles
import "slick-carousel/slick/slick.css";
import "slick-carousel/slick/slick-theme.css";

function EventsSlider() {
  const ArrowButton = ({ direction, onClick }) => {
    return (
      <div
        onClick={onClick}
        style={{
          position: "absolute",
          top: "50%",
          [direction]: "-50px",
          transform: "translateY(-50%)",
          backgroundColor: "#FFFF",
          borderRadius: "50%",
          width: "40px",
          height: "40px",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          cursor: "pointer",
          zIndex: 10,
        }}
      >
        <span style={{ color: "#00b666", fontSize: "20px" }}>
          {direction === "left" ? "<" : ">"}
        </span>
      </div>
    );
  };

  const settings = {
    dots: true,
    arrows: true,
    infinite: true,
    autoplay: true,
    autoplaySpeed: 5000,
    slidesToShow: 1,
    slidesToScroll: 1,
    nextArrow: <ArrowButton direction="right" />,
    prevArrow: <ArrowButton direction="left" />,
  };

  return (
    <div style={styles.wrapper}>
      {/* Ek görseller */}
      <div style={styles.shapeDots}>
        <img
          src="assets/shape-dots.svg"
          alt="Dots Shape"
          style={{ width: "50px", height: "50px", marginLeft:"300px" }}
        />
      </div>
      <div style={styles.kesikCizgi}>
        <img
          src="assets/kesik-yan-cizgi.svg"
          alt="Kesik Çizgi"
          style={{ width: "142px", height: "142px" }}
        />
      </div>

      {/* Slider */}
      <div style={styles.content}>
        <Slider {...settings} style={styles.slider}>
          <div style={styles.contentBox}>
            <img
              src="https://www.techcareer.net/_next/image?url=https%3A%2F%2Fcdn.gcp.techcareer.net%2F1112_412_2_cd52574011%2F1112_412_2_cd52574011.png&w=1200&q=100"
              alt="Slide 1"
              style={styles.image}
            />
          </div>
          <div style={styles.contentBox}>
            <img
              src="https://www.techcareer.net/_next/image?url=https%3A%2F%2Fcdn.gcp.techcareer.net%2F1112_412_2_cd52574011%2F1112_412_2_cd52574011.png&w=1200&q=100"
              alt="Slide 2"
              style={styles.image}
            />
          </div>
          <div style={styles.contentBox}>
            <img
              src="https://www.techcareer.net/_next/image?url=https%3A%2F%2Fcdn.gcp.techcareer.net%2F1112_412_2_cd52574011%2F1112_412_2_cd52574011.png&w=1200&q=100"
              alt="Slide 3"
              style={styles.image}
            />
          </div>
        </Slider>
      </div>

      {/* Alt Mavi Bar */}
      <div style={styles.bottomBar}></div>
    </div>
  );
}

const styles = {
  wrapper: {
    position: "relative",
    width: "100vw",
    margin: "0 auto",
    backgroundColor: "rgb(246, 248, 255)",
    overflow: "hidden",
  },
  shapeDots: {
    position: "fixed",
    marginleft: "3px",
    zIndex: 5,
  },
  kesikCizgi: {
    position: "fixed",
    right: "1%",
    zIndex: 5,
  },
  content: {
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    width: "100%",
    margin: "0",
  },
  slider: {
    width: "100%",
    maxWidth: "1200px",
    margin: "0 auto",
  },
  contentBox: {
    width: "100%",
    height: "400px",
    margin: "0",
    padding: "0",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
  },
  image: {
    width: "auto",
    maxHeight: "100%",
    objectFit: "contain",
    borderRadius: "5px",
    boxShadow: "0 4px 8px rgba(0, 0, 0, 0.2)",
  },
  bottomBar: {
    width: "100%",
    height: "100px",
    backgroundColor: "#293349",
    marginTop: "5px",
  },
};


export default EventsSlider;
